(()=>{'use strict';
let plants=[],units=[],state,baseline=[],expanded=new Set(),busy=false;
const key='uhe-ctg-2027-v1',cfg=window.UHE_CONFIG||{},Y=cfg.year||2027;
const f=(v,d=6)=>v===null||!Number.isFinite(Number(v))?'—':fmt(Number(v),d);
const initial=()=>CTGModel.initial(plants,units,cfg);
function save(){try{localStorage.setItem(key,JSON.stringify(state))}catch(e){$('ctgMessage').textContent='Salvamento local indisponível. Exporte o cenário.'}}
function summary(){return CTGModel.summarize(state,plants,units,Engine.refs)}
function dirty(){return SheetBridge.changes(baseline,state.units)}
function update(){
 const result=summary();
 $('ctgCount').textContent=result.plantCount;$('ctgUgs').textContent=result.unitCount;$('ctgDisp').textContent=f(result.availability,3)+(result.availability===null?'':'%');$('ctgMw').textContent=f(result.equivalent,3)+(result.equivalent===null?'':' MW');
 $('ctgMessage').textContent=result.invalid?result.invalid+' UG(s) com dados inválidos.':result.plantCount+' UHEs · '+result.unitCount+' UGs · '+f(result.power,3)+' MW';
 $('ctgBands').innerHTML=result.bands.map((b,k)=>`<tr><td>${labels[k]}</td><td>${b.plants}</td><td>${b.n}</td><td>${f(b.teif)}</td><td>${f(b.ip)}</td><td>${f(b.disp)}</td></tr>`).join('');
 for(const p of result.plants){const tr=$('ctg-'+p.id);if(!tr)continue;tr.classList.toggle('invalid',p.selected&&p.units.some(u=>u.include&&u.disp===null));for(const [name,value] of Object.entries({n:p.n,power:f(p.power,3),band:p.bands.filter(Boolean).join(' / ')||'—',d:f(p.disp),ref:f(p.refDisp),delta:p.disp===null||p.refDisp===null?'—':f(p.disp-p.refDisp)}))tr.querySelector('[data-result="'+name+'"]').textContent=value;
 for(const field of ['teif','ip']){const input=tr.querySelector('[data-field="'+field+'"]');if(document.activeElement!==input)input.value=p[field]===null?'':Number(p[field].toFixed(6))}
 const edited=p.units.some(u=>!SheetBridge.equal(u,baseline.find(b=>b.id===u.id)||{}));tr.querySelector('[data-result="source"]').textContent=edited?'Cenário por UG':p.units.some(u=>u.teif!==p.units[0]?.teif||u.ip!==p.units[0]?.ip)?'Taxas por UG':'Base configurada';
 }
 for(const u of result.units){const row=$('ug-'+u.id);if(row){row.classList.toggle('invalid',u.include&&u.disp===null);row.querySelector('[data-ug-result="disp"]').textContent=f(u.disp);row.querySelector('[data-ug-result="band"]').textContent=u.band||'—'}}
 $('ctgUnits').innerHTML=units.map(u=>{const current=result.units.find(r=>r.id===u.id);return `<tr><td>${esc(u.plant)}</td><td>${esc(u.ug)}</td><td>${f(current?.mw??u.mw,2)}</td><td>${current?.selected?'Incluída':u.eligible?'Fora da seleção':'Fora do cálculo'}</td><td>${esc(u.reason)}</td></tr>`}).join('');
 $('sheetDirty').textContent=dirty().length?dirty().length+' UG(s) com alterações locais.':'Sem alterações de UGs para salvar.';
 save();
}
function unitTable(p){return `<tr id="units-${p.id}" class="ug-panel" ${expanded.has(p.id)?'':'hidden'}><td colspan="11"><table class="ug-table"><thead><tr><th>Incluir</th><th>UG</th><th>Potência MW</th><th>TEIF %</th><th>IP %</th><th>D %</th><th>Faixa</th></tr></thead><tbody>${p.units.map(u=>`<tr id="ug-${u.id}"><td><input type="checkbox" aria-label="Incluir ${esc(p.name)} ${esc(u.ug)}" data-unit="${u.id}" data-unit-field="include" ${u.include?'checked':''}></td><td><b>${esc(u.ug)}</b></td>${['mw','teif','ip'].map(field=>`<td><input type="number" aria-label="${field==='mw'?'Potência MW':field.toUpperCase()+' %'} ${esc(p.name)} ${esc(u.ug)}" min="${field==='mw'?'0.000001':'0'}" max="${field==='mw'?'1300':'100'}" step="0.000001" value="${u[field]}" data-unit="${u.id}" data-unit-field="${field}"></td>`).join('')}<td data-ug-result="disp">${f(u.disp)}</td><td data-ug-result="band">${u.band||'—'}</td></tr>`).join('')}</tbody></table></td></tr>`}
function render(){
 $('ctgStudy').value=state.study;$('ctgNotes').value=state.notes;$('ctgParticipation').checked=state.participation;
 $('ctgRows').innerHTML=summary().plants.filter(p=>p.kind==='operada'||state.participation).map(p=>`<tr id="ctg-${p.id}"><td><input aria-label="Incluir ${esc(p.name)}" type="checkbox" data-id="${p.id}" data-field="include" ${p.include?'checked':''}></td><td><b>${esc(p.name)}</b><small>${p.id} · ${p.kind==='operada'?'OPERAÇÃO CTG':'PARTICIPAÇÃO'}</small><button class="ug-toggle" id="toggle-${p.id}" data-expand="${p.id}" aria-expanded="${expanded.has(p.id)}" aria-controls="units-${p.id}">${expanded.has(p.id)?'▾':'▸'} Editar UGs</button></td><td data-result="n">${p.n}</td><td data-result="power"></td><td><span data-result="band"></span><small>Faixa por UG</small></td>${['teif','ip'].map(field=>`<td><input type="number" aria-label="${field.toUpperCase()} ${Y} ${esc(p.name)} — aplicar a todas as UGs" title="Aplicar a todas as UGs da usina" min="0" max="100" step="0.000001" value="${p[field]??''}" data-id="${p.id}" data-field="${field}"></td>`).join('')}<td data-result="d"></td><td data-result="ref"></td><td data-result="delta"></td><td class="source"><span data-result="source"></span><br><a href="${esc(p.source)}" target="_blank" rel="noopener">Cadastro CTG ↗</a><br>${esc(p.ceg)}</td></tr>${unitTable(p)}`).join('');update();
}
$('ctgRows').onclick=e=>{const button=e.target.closest('[data-expand]');if(!button)return;const id=button.dataset.expand;if(expanded.has(id))expanded.delete(id);else expanded.add(id);$('units-'+id).hidden=!expanded.has(id);button.setAttribute('aria-expanded',String(expanded.has(id)));button.textContent=(expanded.has(id)?'▾':'▸')+' Editar UGs'};
$('ctgRows').oninput=$('ctgRows').onchange=e=>{const el=e.target;if(el.dataset.unit){const r=state.units.find(u=>u.id===el.dataset.unit),field=el.dataset.unitField;if(!r||!['mw','teif','ip','include'].includes(field))return;r[field]=field==='include'?el.checked:el.value===''?'':Number(el.value)}else{const r=state.rows.find(r=>r.id===el.dataset.id),field=el.dataset.field;if(!r||!['include','teif','ip'].includes(field))return;if(field==='include')r.include=el.checked;else{r[field]=el.value===''?'':Number(el.value);r.edited=true;for(const u of state.units.filter(u=>units.find(x=>x.id===u.id)?.plantId===r.id)){u[field]=r[field];const input=$('ug-'+u.id)?.querySelector('[data-unit-field="'+field+'"]');if(input)input.value=r[field]}}}update()};
$('ctgStudy').oninput=()=>{state.study=$('ctgStudy').value;save()};$('ctgNotes').oninput=()=>{state.notes=$('ctgNotes').value;save()};
$('ctgParticipation').onchange=()=>{state.participation=$('ctgParticipation').checked;state.rows.find(r=>r.id==='SMN').include=state.participation;render()};
$('ctgReset').onclick=()=>{if(!confirm('Substituir o cenário pelos valores da configuração?'))return;state=initial();render()};
function exportable(){const checked=CTGModel.validateUnits(state,plants,units,cfg),r=summary();return {...checked,ano:Y,data_consulta:cfg.date,base:'Configuração por UG',status:'Cenário interno; não homologado',metodo_portfolio:'Soma(P*D)/Soma(P); capacidade integral',resultados:r.plants.map(p=>({id:p.id,nome:p.name,ceg:p.ceg,incluida:p.selected,ugs:p.n,unidades:p.unitIds,potencia_mw:p.power,teif_pct:p.teif,ip_pct:p.ip,d_cenario_pct:p.disp,d_tabela_pct:p.refDisp})),resultados_ugs:r.units}}
$('ctgBackup').onclick=()=>{try{download('CTG_Brasil_cenario_'+Y+'.json',JSON.stringify(exportable(),null,2))}catch(e){toast(e.message)}};
$('ctgExport').onclick=()=>{try{const data=exportable().resultados;download('CTG_Brasil_disponibilidade_'+Y+'.csv','\uFEFF'+csv([['sigla','usina','ceg','incluida','ugs','unidades','potencia_mw','teif_cenario_pct','ip_cenario_pct','d_cenario_pct','d_tabela_pct','hipotese'],...data.map(r=>[r.id,r.nome,r.ceg,r.incluida?1:0,r.ugs,r.unidades.join(', '),r.potencia_mw,r.teif_pct,r.ip_pct,r.d_cenario_pct,r.d_tabela_pct,state.notes])]),'text/csv;charset=utf-8')}catch(e){toast(e.message)}};
$('ctgUnitsExport').onclick=()=>{try{const r=exportable();download('CTG_Brasil_UGs_'+Y+'.csv','\uFEFF'+csv([['unidade_id','usina','ug','potencia_mw','incluir_cenario','teif_pct','ip_pct','disponibilidade_pct'],...r.resultados_ugs.map(u=>[u.id,u.plant,u.ug,u.mw,u.include?1:0,u.teif,u.ip,u.disp])]),'text/csv;charset=utf-8')}catch(e){toast(e.message)}};
$('ctgImport').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>1024*1024)throw Error('Limite de 1 MB.');state=CTGModel.validateUnits(JSON.parse(await file.text()),plants,units,cfg);render();toast('Cenário CTG importado.')}catch(err){$('ctgMessage').textContent='Importação recusada: '+err.message}finally{e.target.value=''}};
function working(value){busy=value;for(const id of ['sheetSave','sheetLoad'])$(id).disabled=value}
function runCloud(action){if(busy)return;working(true);$('sheetStatus').textContent='Aguardando autorização Google…';SheetBridge.authorize().then(action).catch(e=>{$('sheetStatus').textContent=e.message}).finally(()=>working(false))}
$('sheetSave').onclick=()=>{try{CTGModel.validateUnits(state,plants,units,cfg);const count=dirty().length;if(!count){$('sheetStatus').textContent='Nenhuma alteração para salvar.';return}if(!confirm('Salvar alterações de '+count+' UG(s) na planilha compartilhada?'))return;const snapshot=structuredClone(state);runCloud(async()=>{$('sheetStatus').textContent='Salvando UGs…';const result=await SheetBridge.save(baseline,snapshot,plants,units),compiled=ConfigModel.compile(result.payload);for(const row of state.units){const before=snapshot.units.find(u=>u.id===row.id),remote=compiled.units.find(u=>u.id===row.id);if(remote&&SheetBridge.equal(row,before))Object.assign(row,{mw:remote.mw,teif:remote.teif,ip:remote.ip,include:remote.include})}units=compiled.units;plants=compiled.plants;baseline=units.filter(u=>u.eligible).map(u=>({...u}));window.UHE_ACCEPT_PAYLOAD(result.payload);$('sheetStatus').textContent=result.count+' UG(s) salvas e verificadas na planilha.';render()})}catch(e){$('sheetStatus').textContent=e.message}};
$('sheetLoad').onclick=()=>{if(!confirm('Carregar a planilha e substituir o cenário atual? Exporte um backup para conservar alterações.'))return;runCloud(async()=>{$('sheetStatus').textContent='Carregando planilha…';const payload=await SheetBridge.read(),compiled=ConfigModel.compile(payload);localStorage.setItem('uhe-base-config-v1',JSON.stringify(payload));localStorage.setItem(key,JSON.stringify(CTGModel.initial(compiled.plants,compiled.units,compiled.settings)));location.reload()})};
(async()=>{try{[plants,units]=await Promise.all(['ctg.json','ctg-units.json'].map(url=>fetch(url).then(r=>{if(!r.ok)throw Error('Cadastro CTG indisponível.');return r.json()})));baseline=units.filter(u=>u.eligible).map(u=>({...u}));state=initial();try{const saved=localStorage.getItem(key);if(saved)state=CTGModel.validateUnits(JSON.parse(saved),plants,units,cfg)}catch(e){$('ctgMessage').textContent='Cenário salvo incompatível: base configurada carregada.'}render();const op=plants.filter(p=>p.kind==='operada'&&p.includeDefault!==false),all=plants.filter(p=>p.kind==='participacao'||p.includeDefault!==false);$('configDefaultTotals').textContent='Cadastro padrão: '+op.reduce((s,p)=>s+p.n,0)+' UGs · '+f(op.reduce((s,p)=>s+p.power,0),2)+' MW.';$('configOptionalTotals').textContent='Com participações: '+all.reduce((s,p)=>s+p.n,0)+' UGs · '+f(all.reduce((s,p)=>s+p.power,0),2)+' MW.';document.querySelector('#ctg h2').textContent='Cenário de disponibilidade · '+Y;document.querySelector('button[data-tab=ctg]').textContent=Y+' · CTG Brasil';$('sheetStatus').textContent=cfg.googleClientId?'Salvamento com autorização Google.':'Gravação pendente: configure google_oauth_client_id na aba Parametros.';}catch(e){$('ctgMessage').textContent=e.message}})();
})();
